// Recorre la tanda entera (ver n8n/parches/2026-09-29-correo-tandas-y-atrasados.mjs).
const procesar = (j) => {
const text = (v) => String(v ?? '').trim();

const extractEmail = (value) => {
  const raw = text(value);
  const match =
    raw.match(/<\s*([^<>\s]+@[^<>\s]+)\s*>/) ||
    raw.match(/([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i);
  return String(match?.[1] || '').trim().toLowerCase();
};

const fromRaw = text(j.From || j.from || j.sender);
const emailCliente = extractEmail(fromRaw);

if (!emailCliente) {
  throw new Error(`No se pudo extraer el remitente desde From="${fromRaw}"`);
}

const asuntoOriginal = text(j.Subject || j.subject || 'Sin asunto');
const mensaje = text(j.textPlain || j.text || j.body || j.snippet || 'El correo no contiene texto visible.')
  .replace(/\u0000/g, '')
  .slice(0, 12000);

// En esta versión estable respondemos desde ventas.
// Luego podremos separar soporte/contacto con etiquetas de Gmail.
const replyFrom = 'ventas@transtech.com.py';

const propio =
  emailCliente === 'transtecheos@gmail.com' ||
  emailCliente.endsWith('@transtech.com.py');

const automatico =
  /(mailer-daemon|postmaster|no-?reply|do-?not-?reply)/i.test(fromRaw);

if (propio || automatico) {
  return [];
}

// Respuestas automáticas, correos masivos y hilos largos: contestarles arma un
// ida y vuelta sin fin desde ventas@ (ver n8n/parches/2026-09-29-correo-sin-ida-y-vuelta.mjs).
const etiquetas = Array.isArray(j.labelIds)
  ? j.labelIds
  : (Array.isArray(j.labels) ? j.labels.map((l) => (l && l.id) || l) : []);
const masivo = etiquetas.some((l) =>
  ['SPAM', 'CATEGORY_PROMOTIONS', 'CATEGORY_SOCIAL', 'CATEGORY_UPDATES', 'CATEGORY_FORUMS'].includes(l),
);
const respuestaAutomatica =
  /(respuesta autom|automatic reply|auto.?reply|autoreply|out of office|fuera de (la )?oficina|de vacaciones|undeliverable|no se pudo entregar|delivery status|mail delivery)/i.test(asuntoOriginal);
const hiloLargo = (asuntoOriginal.match(/\b(re|rv|fw|fwd)\s*:/gi) || []).length >= 3;

if (masivo || respuestaAutomatica || hiloLargo) {
  return [];
}

// Tope: tres respuestas por remitente y por día.
const memoria = $getWorkflowStaticData('global');
const hoy = new Date().toISOString().slice(0, 10);
if (!memoria.respuestas || memoria.respuestas.dia !== hoy) {
  memoria.respuestas = { dia: hoy, por: {} };
}
const yaRespondidas = memoria.respuestas.por[emailCliente] || 0;
if (yaRespondidas >= 3) {
  return [];
}
memoria.respuestas.por[emailCliente] = yaRespondidas + 1;

return [{
  json: {
    gmail_message_id: j.id || '',
    gmail_thread_id: j.threadId || '',
    remitente_original: fromRaw,
    email_cliente: emailCliente,
    canal: 'ventas',
    reply_from: replyFrom,
    asunto_original: asuntoOriginal,
    asunto_respuesta: /^re:/i.test(asuntoOriginal) ? asuntoOriginal : `Re: ${asuntoOriginal}`,
    mensaje
  }
}];
};

const salida = [];
const MAXIMO_MS = 24 * 60 * 60 * 1000;
for (const item of $input.all()) {
  const j = item.json;
  const recibido = Number(j.internalDate || 0);
  if (!recibido || Date.now() - recibido > MAXIMO_MS) continue;
  try {
    const r = procesar(j);
    if (Array.isArray(r)) salida.push(...r);
  } catch (error) {
    // Un correo ilegible no tira la tanda entera.
  }
}
return salida;

